paragraph","content":[{"type":"text","text":"_","marks":[{"type":"textColor","attrs":{"color":"#1f4e79"}}]},{"type":"text","text":"www.ogalwc.org","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}},{"type":"link","attrs":{"href":"https://url.de.m.mimecastprotect.com/s/HENlC57BvWhZJW1BjsyiOukbkpx?domain=ogalwc.org"}}]},{"type":"text","text":"_   "}]},{"type":"paragraph","content":[{"type":"text","text":"“Water is our most precious and interconnected natural resource. It sustains all ecosystems, communities,","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}}]},{"type":"text","text":"  "},{"type":"text","text":"and economies from local watersheds to the seas. It’s vital to sustaining","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}}]},{"type":"text","text":"  "},{"type":"text","text":"our health, safety, and the","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}}]},{"type":"text","text":"  "},{"type":"text","text":"environments in which we live and work.","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}}]},{"type":"text","text":"  "},{"type":"text","text":"Simply put, water is life.” – Alexandra Cousteau","marks":[{"type":"em"},{"type":"textColor","attrs":{"color":"#1f4e79"}}]}]}],"attrs":{"title":"Signature"}}{adf}

